import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('passes valid input and undeclared properties through unchanged exactly once', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    let receivedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        executorCalls += 1;
        receivedInput = input;
        return JSON.stringify(input);
      }
    );
    const input = {location: 'Paris', traceId: 'trace-1'};

    await registry.execute('get_weather', input);

    expect({executorCalls, receivedInput}).toEqual({executorCalls: 1, receivedInput: input});
  });

  it('validates function-valued definitions against the schema resolved for each call', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    let definitionCalls = 0;
    const citySchema = {type: 'object', properties: {city: {type: 'string'}}, required: ['city']};
    const locationSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    registry.register(
      () => {
        definitionCalls += 1;
        return {
          name: 'get_weather',
          description: 'Get weather for a location',
          inputSchema: definitionCalls === 2 ? citySchema : locationSchema,
        };
      },
      async input => {
        executorCalls += 1;
        return JSON.stringify(input);
      }
    );

    await registry.execute('get_weather', {city: 'Paris'});
    const response = await registry.execute('get_weather', {city: 'Paris'});

    expect({
      rejectionNamesCurrentRequiredField: response.result.includes('location') && /required/i.test(response.result),
      executorCalls,
    }).toEqual({rejectionNamesCurrentRequiredField: true, executorCalls: 1});
  });

  it('throws unchanged for an unknown tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });
});
import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validateInput?: ValidateFunction;
}

const ajv = new Ajv({
  strict: false,
  validateFormats: false,
  coerceTypes: false,
  useDefaults: false,
  allErrors: true,
} as unknown as ConstructorParameters<typeof Ajv>[0]);

function validationMessage(errors: ErrorObject[] | null | undefined): string {
  const details = (errors ?? []).map(error => {
    const params = error.params as Record<string, unknown>;
    const errorLocation = error as ErrorObject & {instancePath?: string; dataPath?: string};
    const path = errorPath(String(errorLocation.instancePath ?? errorLocation.dataPath ?? ''));

    if (error.keyword === 'required') {
      path.push(String(params.missingProperty));
      return `${path.join('.') || '<root>'} is required`;
    }

    const field = path.join('.') || '<root>';
    return messageForConstraint(error.keyword, field, params);
  });

  return `Input validation failed: ${details.join('; ')}`;
}

function messageForConstraint(keyword: string, field: string, params: Record<string, unknown>): string {
  if (keyword === 'type') return `${field} must be ${String(params.type)}`;
  if (keyword === 'enum') return `${field} must be one of the allowed values`;
  return `${field} failed the ${keyword} constraint`;
}

function errorPath(instancePath: string): string[] {
  return instancePath
    .split('/')
    .filter(Boolean)
    .map(part => part.replace(/~1/g, '/').replace(/~0/g, '~'));
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validateInput = typeof definition === 'function' ? undefined : this.compileInputSchema(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validateInput});
  }

  private compileInputSchema(definition: ToolDefinition): ValidateFunction {
    try {
      return ajv.compile(definition.inputSchema);
    } catch (error) {
      throw new Error(
        `Invalid inputSchema for tool ${definition.name}: ${error instanceof Error ? error.message : String(error)}`,
        {cause: error}
      );
    }
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns input-schema rejections as tool results; throws only for unknown names (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    let validateInput = tool.validateInput;
    try {
      if (!validateInput) {
        validateInput = this.dynamicValidators.get(definition.inputSchema);
      }
      if (!validateInput) {
        validateInput = this.compileInputSchema(definition);
        this.dynamicValidators.set(definition.inputSchema, validateInput);
      }
    } catch {
      return {result: 'Tool input schema is invalid'};
    }
    if (!validateInput(input)) return {result: validationMessage(validateInput.errors)};
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
